<?php
if('staging'!==wp_get_environment_type())WP_CLI::error('Staging only');
$comments=get_comments(array('post_id'=>657,'status'=>'all','search'=>'STAGING QA PHOTO TEST','number'=>5));$out=array();foreach($comments as$c){$photo=get_comment_meta($c->comment_ID,'_sp_review_photo',true);$base=sp_private_upload_dir();$path=!is_wp_error($base)&&!empty($photo['public_file'])?$base.'/'.$photo['public_file']:'';$image=$path&&is_file($path)?getimagesize($path):false;$out[]=array('id'=>(int)$c->comment_ID,'moderation_status'=>$c->comment_approved,'photo_stored'=>!!$image,'mime'=>$image['mime']??null,'private_permissions'=>$path&&is_file($path)?substr(sprintf('%o',fileperms($path)),-4):null);if('0'!==$c->comment_approved||!$image)WP_CLI::error('Review moderation/upload check failed');}if(!$out)WP_CLI::error('Review fixture missing');echo wp_json_encode(array('review_photo_checks'=>$out,'public_review_count'=>wc_get_product(657)->get_review_count()))."\n";
